select sum(goods_plus_discount) as goods_plus_discount,DATE_FORMAT(order_goods_time, '%Y-%m-%d %H:%i:%s') as
order_goods_time
FROM ${database.prefix.order}hou_order_goods where order_id = #{orderId}

    and goods_id in

        #{id}

SELECT a.order_id AS orderId, b.order_create_time AS orderCreateTime, b.order_status AS orderStatus, b.pay_code AS payCode, a.order_status AS orderCommissionStatus, sum(IF(a.tg_one_user_id = #{param.userId}, a.one_tg_commission - a.return_one_tg_commission, 0)) AS oneTgCommission, sum(IF(a.tg_two_user_id = #{param.userId}, a.two_tg_commission - a.return_two_tg_commission, 0)) AS twoTgCommission, sum(IF(a.share_user_id = #{param.userId}, a.fx_commission - a.return_fx_commission, 0)) AS shareCommission, a.buy_user_id AS userId, a.buy_user_name AS userName, a.buy_user_avatar AS userAvatar FROM ${database.prefix.order}hou_order_commission a LEFT join ${database.prefix.order}hou_order_base b ON a.order_id = b.order_id
(a.share_user_id = #{param.userId} or a.tg_one_user_id = #{param.userId} or a.tg_two_user_id = #{param.userId})
and a.shop_id = #{param.shopId}
and a.order_id like CONCAT('%',#{param.orderId},'%')
and b.order_status = #{param.orderStatus}
and b.order_create_time >= #{param.orderStartTime}
and b.order_create_time <= #{param.orderEndTime}
and a.goods_name like CONCAT('%',#{param.goodsName},'%')
and a.buy_user_name like CONCAT('%',#{param.userName},'%')
group by a.order_id

SELECT a.order_id AS orderId, b.order_create_time AS orderCreateTime, b.order_status AS orderStatus, b.pay_code AS payCode, a.order_status AS orderCommissionStatus, sum(IF(a.tg_one_user_id = #{param.userId}, a.one_tg_commission - a.return_one_tg_commission, 0)) AS oneTgCommission, sum(IF(a.tg_two_user_id = #{param.userId},a.two_tg_commission - a.return_two_tg_commission, 0)) AS twoTgCommission, sum(IF(a.share_user_id = #{param.userId},a.fx_commission - a.return_fx_commission, 0)) AS shareCommission, a.buy_user_id AS userId, a.buy_user_name AS userName, a.buy_user_avatar AS userAvatar FROM ${database.prefix.order}hou_order_commission a LEFT join ${database.prefix.order}hou_order_base b ON a.order_id = b.order_id where (a.share_user_id = #{param.userId} or a.tg_one_user_id = #{param.userId} or a.tg_two_user_id = #{param.userId})
and a.order_id like CONCAT('%',#{param.orderId},'%')
and a.buy_user_id = #{param.buyUserId}
and a.order_status = #{param.orderStatus}
group by a.order_id order by a.create_time desc

SELECT a.order_id AS orderId, b.order_create_time AS orderCreateTime, b.order_status AS orderStatus, b.pay_code AS payCode, a.order_status AS orderCommissionStatus, sum(a.one_tg_commission - a.return_one_tg_commission) AS oneTgCommission, sum(a.two_tg_commission - a.return_two_tg_commission) AS twoTgCommission, sum(a.fx_commission - a.return_fx_commission) AS shareCommission, a.buy_user_id AS userId, a.buy_user_name AS userName, a.buy_user_avatar AS userAvatar FROM ${database.prefix.order}hou_order_commission a LEFT join ${database.prefix.order}hou_order_base b ON a.order_id = b.order_id
(a.share_user_id = #{param.userId} or a.tg_one_user_id = #{param.userId} or a.tg_two_user_id = #{param.userId})
and a.shop_id = #{param.shopId}
and a.order_id like CONCAT('%',#{param.orderId},'%')
and b.order_status = #{param.orderStatus}
and a.order_status = 1
and a.order_status = #{param.orderStatus}
and b.order_create_time >= #{param.orderStartTime}
and b.order_create_time <= #{param.orderEndTime}
and a.goods_name like CONCAT('%',#{param.goodsName},'%')
and a.buy_user_name like CONCAT('%',#{param.userName},'%')
group by a.order_id ORDER BY b.order_create_time DESC
